import numpy as np

class GraphRNN:
    def __init__(self, max_nodes, hidden_dim):
        self.max_nodes = max_nodes
        self.hidden_dim = hidden_dim
        self.W_graph = np.random.randn(hidden_dim, hidden_dim) * 0.01
        self.U_graph = np.random.randn(hidden_dim, hidden_dim) * 0.01
        self.W_node = np.random.randn(2, hidden_dim) * 0.01
        self.U_node = np.random.randn(hidden_dim, hidden_dim) * 0.01
        self.W_out = np.random.randn(hidden_dim, 1) * 0.01
    def bfs_ordering(self, adj):
        order, visited, queue = [], set(), [0]
        visited.add(0)
        while queue:
            node = queue.pop(0)
            order.append(node)
            for nb in range(len(adj)):
                if adj[node, nb] == 1 and nb not in visited:
                    visited.add(nb)
                    queue.append(nb)
        return order
    def graph_rnn_step(self, h_prev, x):
        return np.tanh(self.W_graph @ x + self.U_graph @ h_prev)
    def node_rnn_step(self, h_prev, edge_bit):
        x = np.array([float(edge_bit), 1.0])
        return np.tanh(self.W_node.T @ x + self.U_node @ h_prev)
    def generate_adj_row(self, h_graph):
        adj_row = []
        h_node = np.zeros(self.hidden_dim)
        for _ in range(self.max_nodes):
            logit = h_node @ self.W_out
            prob = 1 / (1 + np.exp(-logit))
            edge_bit = 1 if np.random.random() < prob else 0
            adj_row.append(edge_bit)
            h_node = self.node_rnn_step(h_node, edge_bit)
        return np.array(adj_row)
    def generate_graph(self):
        adj = np.zeros((self.max_nodes, self.max_nodes))
        h_graph = np.zeros(self.hidden_dim)
        for i in range(self.max_nodes):
            adj_row = self.generate_adj_row(h_graph)
            adj[i, :i+1] = adj_row[:i+1]
            h_graph = self.graph_rnn_step(h_graph, adj_row)
        adj = np.maximum(adj, adj.T)
        return adj
